import crypto from "node:crypto";

import { hasVolcanoAppKey, ProviderConfig } from "@/providers/shared/config";

const accessKey = ProviderConfig.volcanoSecretId;
const secretKey = ProviderConfig.volcanoSecretKey;

/**
 * Generate Volcano Sign.
 *
 * Docs: https://www.volcengine.com/docs/4640/65067
 *
 * Ref: https://github.com/KrisLee1/panda-dict/blob/main/src/assets/script/APIs.js#L134
 */
export const genVolcanoSign = function (query, params) {
  if (!hasVolcanoAppKey()) {
    return undefined;
  }

  const Query = {
    query: query,
    toString: function () {
      let queryList = [];
      for (let key of Object.keys(this.query).sort()) {
        queryList.push(`${key}=${this.query[key]}`);
      }
      return queryList.join("&");
    },
  };

  const Body = {
    body: params,
    toString: function () {
      return JSON.stringify(this.body);
    },
  };

  const Credentials = {
    ak: accessKey,
    sk: secretKey,
    service: "translate",
    region: "cn-north-1",
  };

  function getXDate() {
    function leftPad(n) {
      return n < 10 ? "0" + n : n;
    }
    const now = new Date();
    const format = [
      now.getUTCFullYear(),
      leftPad(now.getUTCMonth() + 1),
      leftPad(now.getUTCDate()),
      "T",
      leftPad(now.getUTCHours()),
      leftPad(now.getUTCMinutes()),
      leftPad(now.getUTCSeconds()),
      "Z",
    ];
    return format.join("");
  }

  const curTime = getXDate();

  const MetaData = {
    algorithm: "HMAC-SHA256",
    service: Credentials.service,
    region: Credentials.region,
    date: curTime.substring(0, 8),
    getCredentialScope: function () {
      return `${this.date}/${this.region}/${this.service}/request`;
    },
  };

  const Header = {
    headers: {
      "Content-Type": "application/json",
      "X-Date": curTime,
      "X-Content-Sha256": crypto.createHash("sha256").update(Body.toString()).digest("hex"),
    },
    getSignedHeaders: function () {
      let headerList = [];
      for (let key of Object.keys(this.headers).sort()) {
        headerList.push(key.toLowerCase());
      }
      return headerList.join(";");
    },
    toString: function () {
      let str = "";
      for (let key of Object.keys(this.headers).sort()) {
        str += `${key.toLowerCase()}:${this.headers[key]}\n`;
      }
      return str;
    },
  };

  const getSigningKey = function (sk, date, region, service) {
    const kdate = crypto.createHmac("sha256", sk).update(date).digest();
    const kregion = crypto.createHmac("sha256", kdate).update(region).digest();
    const kservice = crypto.createHmac("sha256", kregion).update(service).digest();
    return crypto.createHmac("sha256", kservice).update("request").digest();
  };

  const canonicalRequest = [
    "POST",
    "/",
    Query.toString(),
    Header.toString(),
    Header.getSignedHeaders(),
    Header.headers["X-Content-Sha256"],
  ].join("\n");
  const hashCanonicalRequest = crypto.createHash("sha256").update(canonicalRequest).digest("hex");
  const signing_str = [MetaData.algorithm, curTime, MetaData.getCredentialScope(), hashCanonicalRequest].join("\n");
  const signing_key = getSigningKey(Credentials.sk, MetaData.date, MetaData.region, MetaData.service);
  const sign = crypto.createHmac("sha256", signing_key).update(signing_str).digest("hex");

  const Authorization = [
    `${MetaData.algorithm} Credential=${Credentials.ak}/${MetaData.getCredentialScope()}`,
    "SignedHeaders=" + Header.getSignedHeaders(),
    `Signature=${sign}`,
  ];

  Header.headers["Authorization"] = Authorization.join(", ");

  return {
    getUrl: function () {
      return "https://open.volcengineapi.com/?" + Query.toString();
    },
    getConfig: function () {
      return {
        headers: Header.headers,
      };
    },
  };
};
